import { TextDecoder } from 'node:util';
import { checkpoint } from './runtime.js';
import { validateState } from './schema.js';
import { readState, writeState } from './store.js';
import { encode } from './wire.js';

const decoder = new TextDecoder('utf-8', { fatal: true });

function invalidBackup(cause) {
  const error = new Error('Invalid backup');
  error.code = 'INVALID_BACKUP';
  error.cause = cause;
  return error;
}

function currentState(document) {
  return {
    preferences: document.account.preferences,
    lanes: document.board.lanes.map(row => ({
      id: row.id,
      title: row.title,
    })),
    events: document.board.events.map(row => ({
      id: row.id,
      lane: row.lane,
      body: row.body,
      done: row.done,
      extra: row.extra,
    })),
    blobs: document.blobs.map(row => ({
      id: row.id,
      bytes: row.bytes,
      name: row.name,
    })),
  };
}

function legacyState(document) {
  return {
    preferences: document.prefs,
    lanes: document.columns.map(row => ({
      id: row.key,
      title: row.name,
    })),
    events: document.rows.map(row => ({
      id: row.key,
      lane: row.column,
      body: row.text,
      done: row.checked,
      extra: row.attributes,
    })),
    blobs: document.blobs.map(row => ({
      id: row.id,
      bytes: row.bytes,
      name: row.name,
    })),
  };
}

function decodeBackup(bytes) {
  try {
    if (!Buffer.isBuffer(bytes)) throw new TypeError('Backup bytes must be a Buffer');
    const document = JSON.parse(decoder.decode(bytes));
    if (document === null || typeof document !== 'object' || Array.isArray(document)) {
      throw new TypeError('Backup document must be an object');
    }

    let state;
    if (document.schema === 4) state = currentState(document);
    else if (document.schema === 2) state = legacyState(document);
    else throw new TypeError('Unsupported backup schema');

    return validateState(state);
  } catch (error) {
    throw invalidBackup(error);
  }
}

export async function exportBackup(directory) {
  const state = await readState(directory);
  return encode({
    schema: 4,
    account: { preferences: state.preferences },
    board: { lanes: state.lanes, events: state.events },
    blobs: state.blobs,
  });
}

export async function importBackup(directory, bytes) {
  const state = decodeBackup(bytes);

  for (let index = 0; index < state.events.length; index += 1) {
    checkpoint(index + 1);
  }

  await writeState(directory, state);
  return { imported: state.events.length };
}

